    ext.append([i+1,r['name'],f(P),f(dis),f(min(2.5,dis)),f(com),f(pay),f(pk),pc(pk/(d/1.15),0),(f(m) if m is not None else "—"),(pc(d/m-1,0) if m is not None else "—"),(pc(P/m-1,0) if m is not None else "—")])
    c=cost(d); cm=net-c; cmp_=cm/(P/1.15); dcm=d/1.15-c
    cmrows.append([i+1,r['name'],f(c),f(net),f(cm),pc(cmp_,1),EM[cls(cmp_)],f(dcm),f(cm-dcm),pc(net/(d/1.15),0)])
